import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { AdminService } from '../../services/admin.service';
import { Airlines, AirlinesService } from 'src/app/services/airlines.service';

interface Airport {
  _code: string;
  name: string;
  city: string;
}

@Component({
  selector: 'app-admin',
  templateUrl: './admin.component.html',
  styleUrls: ['./admin.component.css']
})
export class AdminComponent implements OnInit {
  inviteForm!: FormGroup;
  airportForm!: FormGroup;

  airlines: Airlines[] = [];
  airports: Airport[] = [];
  editing: { [id: string]: boolean } = {};
  editBuffer: { [id: string]: Airport } = {};

  constructor(private fb: FormBuilder, private adminSvc: AdminService, private airline: AirlinesService) {}

  ngOnInit(): void {
    /*
      data: { 
                        _signature: string,
                        username: string, 
                        name: string, 
                        mail: string, 
                        password: string,
                        passportID: string,
                        roles: 'airline',
                      }
    */
    this.inviteForm = this.fb.group({
      _signature: ['', Validators.required],
      username: ['', Validators.required],
      name: ['', Validators.required],
      mail: ['', Validators.required],
      password: ['', Validators.required],
      passportID: ['', Validators.required],
      roles: 'airline'
    });

    this.airportForm = this.fb.group({
      _code: ['', Validators.required],
      name: ['', Validators.required],
      city: ['', Validators.required]
    });

    this.loadAirports();
    this.loadAirlines();
  }

  // ✉️ Invita compagnia
  inviteCompany(): void {
    if (this.inviteForm.invalid) return;
    this.adminSvc.inviteCompany(this.inviteForm.value).subscribe({
      next: res => {
        alert(`Invito inviato a ${this.inviteForm.value.mail} con password temporanea: ${this.inviteForm.value.password}`);
        this.inviteForm.reset();
      },
      error: err => alert('Errore invio invito: ' + err.message)
    });
  }

  loadAirlines(): void {
    this.airline.getAllAirlines().subscribe({
      next: list => this.airlines = list,
      error: err => console.error(err)
    });
  }
  // 🛫 CRUD aeroporti
  loadAirports(): void {
    this.adminSvc.getAirports().subscribe({
      next: list => this.airports = list,
      error: err => console.error(err)
    });
  }

  addAirport(): void {
    if (this.airportForm.invalid) return;
    this.adminSvc.addAirport(this.airportForm.value).subscribe({
      next: a => {
        this.airports.push(a);
        this.airportForm.reset();
        this.loadAirports();
      },
      error: err => alert('Errore creazione aeroporto')
    });
  }

  startEdit(a: Airport): void {
    this.editing[a._code] = true;
    this.editBuffer[a._code] = { ...a };
  }

  saveEdit(id: string): void {
    const data = this.editBuffer[id];
    this.adminSvc.updateAirport(id, data).subscribe({
      next: updated => {
        const idx = this.airports.findIndex(a => a._code === id);
        if (idx > -1) this.airports[idx] = updated;
        this.cancelEdit(id);
        this.loadAirports();
      },
      error: err => alert('Errore aggiornamento aeroporto')
    });
  }

  cancelEdit(id: string): void {
    delete this.editing[id];
    delete this.editBuffer[id];
  }

  deleteAirport(id: string): void {
    this.adminSvc.deleteAirport(id).subscribe({
      next: () => {
        this.airports = this.airports.filter(a => a._code !== id);
        this.loadAirports();
      },
      error: err => alert('Errore eliminazione aeroporto')
    });
  }

  deleteAirline(id: string): void{
    this.adminSvc.deleteAirline(id).subscribe({
      next: () => {
        this.airlines = this.airlines.filter(a => a._signature !== id);
        this.loadAirlines();
      },
      error: err => alert("Errore eliminazione compagnia aerea")
    });
  }
}
<div class="admin-container">

  <!-- ✉️ INVITO COMPAGNIA -->
  <section class="card">
    <h2>Invita Compagnia Aerea</h2>
    <form [formGroup]="inviteForm" (ngSubmit)="inviteCompany()">
        <input formControlName="_signature" placeholder="Signature" />
        <input formControlName="username" placeholder="Username" />
        <input formControlName="name" placeholder="Nome compagnia" />
        <input formControlName="mail" placeholder="Email amministratore" />
        <input formControlName="passportID" placeholder="passport ID" />
        <input formControlName="password" placeholder="Password" />
        <button type="submit" [disabled]="inviteForm.invalid">Invita</button>
    </form>
  </section>

  <section class="card">
    <h2>Compagnie aeree</h2>
    <table>
        <thead>
          <tr>
            <th>Signature</th>
            <th>Name</th>
            <th>Mail</th>
            <th>Azioni</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let a of airlines">
            <ng-container>
              <td>{{ a._signature }}</td>
              <td>{{ a.name }}</td>
              <td>{{ a.mail }}</td>
              <td class="actions">
                <button (click)="deleteAirline(a._signature!)">🗑️</button>
              </td>
            </ng-container>
          </tr>
        </tbody>
    </table>
  </section>

  <!-- 🛫 GESTIONE AEROPORTI -->
  <section class="card">
    <h2>Aeroporti</h2>
    <form [formGroup]="airportForm" (ngSubmit)="addAirport()" class="inline-form">
      <input formControlName="_code" placeholder="Codice (es. 000)" />
      <input formControlName="name" placeholder="Nome aeroporto (es. FCO)" />
      <input formControlName="city" placeholder="Città" />
      <button type="submit" [disabled]="airportForm.invalid">Aggiungi</button>
    </form>

    <table>
      <thead>
        <tr>
          <th>Codice</th>
          <th>Nome</th>
          <th>Città</th>
          <th>Azioni</th>
        </tr>
      </thead>
      <tbody>
        <tr *ngFor="let a of airports">
          <ng-container *ngIf="!editing[a._code!]; else editTpl">
            <td>{{ a._code }}</td>
            <td>{{ a.name }}</td>
            <td>{{ a.city }}</td>
            <td class="actions">
              <button (click)="startEdit(a)">✏️</button>
              <button (click)="deleteAirport(a._code!)">🗑️</button>
            </td>
          </ng-container>
          <ng-template #editTpl>
            <td><input [(ngModel)]="editBuffer[a._code!]._code" /></td>
            <td><input [(ngModel)]="editBuffer[a._code!].name" /></td>
            <td><input [(ngModel)]="editBuffer[a._code!].city" /></td>
            <td class="actions">
              <button (click)="saveEdit(a._code!)">💾</button>
              <button (click)="cancelEdit(a._code!)">❌</button>
            </td>
          </ng-template>
        </tr>
      </tbody>
    </table>
  </section>
</div>
